   177  static void
   178  destroy_s_exp(s_exp_t *s_exp)
   179  {
   180      if (s_exp == NULL) {
   181          return;
   182      }
   183
   184      for (list_item *li = list_front(s_exp->sub_elements); li; li = list_next(li)) {
   185          sub_element_t *sub_el = (sub_element_t *) li;
   186          if (sub_el->is_block) {
   187              free(sub_el->block.bytes);
   188              sub_el->block.bytes = NULL;
   189              sub_el->block.len = 0;
   190          } else {
   191              destroy_s_exp(&sub_el->s_exp);
   192          }
   193      }
   194      list_destroy(&s_exp->sub_elements);
   195  }
